"Every part of the Mass of 1962 in order, with the Latin you will hear, what it means, and when to kneel, sit, and stand. Follow along on your phone.": "Кожна частина меси 1962 року по черзі: латина, яку ви почуєте, її значення та коли ставати на коліна, сідати й вставати. Стежте з телефона.",
