"Your saved entries, prayer intentions, and novenas. Everything here stays private, stored only in this browser.": "Ваші збережені записи, молитовні наміри й новени. Усе залишається приватним і зберігається лише в цьому браузері.",
"Set aside time for silent prayer, meditation, or a Holy Hour, with a gentle bell to begin and end.": "Виділіть час для мовчазної молитви, роздуму або святої години, з тихим дзвоником на початку й наприкінці.",
