"What the Church believes and why: the core teachings of the faith, with Scripture, the Catechism, and answers to common objections.": "У що вірить Церква і чому: основні вчення віри з Писанням, Катехизмом і відповідями на часті заперечення.",
"Spiritual classics and reference works, with summaries and links.": "Духовна класика й довідкові праці, зі стислим викладом і посиланнями.",
"All 73 books of the Catholic canon to read right here, in the Douay-Rheims translation, with Bishop Challoner’s notes.": "Усі 73 книги католицького канону просто тут, в англійському перекладі Douay-Rheims із примітками єпископа Челлонера.",
