"Your language, how Sanctify looks, the edition you use, and the data kept on this device.": "Ваша мова, вигляд Sanctify, ваше видання й дані на цьому пристрої.",
"Sanctify is translated by hand into Spanish, Polish, French, Portuguese, Italian, German, Russian, and Ukrainian: menus, pages, and the common prayers. Longer texts, such as the lives of the saints, are still in English.": "Sanctify перекладено вручну іспанською, польською, французькою, португальською, італійською, німецькою, російською та українською: меню, сторінки й основні молитви. Довші тексти, як-от житія святих, поки що англійською.",
"More languages (Google Translate)…": "Інші мови (Google Перекладач)…",
"Edition": "Видання",
"The Mass, calendar, and prayers Sanctify follows.": "Меса, календар і молитви, яких дотримується Sanctify.",
