"Read Sanctify in your language. Pages are translated by Google, by machine: prayers and Scripture may not match the approved translations used in your country, and Latin texts stay in Latin.": "Читайте Sanctify своєю мовою. Сторінки перекладає Google, машинно: молитви й Писання можуть не збігатися з затвердженими перекладами вашої країни, а латинські тексти залишаються латиною.",
"Find a language…": "Знайти мову…",
"A Catholic Repository": "Католицьке зібрання",
"The Mass and calendar of the Roman Rite as celebrated in most parishes today.": "Меса й календар римського обряду, як їх звершують сьогодні в більшості парафій.",
"The Missal and calendar of 1962: the Traditional Latin Mass explained, the old feasts, seasons, and Ember Days, and the fifteen mysteries of the Rosary.": "Месал і календар 1962 року: пояснення традиційної латинської меси, давні свята, періоди й дні чотирьох пір року, і п’ятнадцять таїнств вервиці.",
"The Byzantine tradition: the Divine Liturgy, the Jesus Prayer, Byzantine prayers, and the Byzantine calendar.": "Візантійська традиція: Божественна Літургія, Ісусова молитва, візантійські молитви й візантійський календар.",
