"Sanctify also comes in a Traditional Latin edition, with the 1962 calendar and the Latin Mass explained, and an Eastern Catholic edition for the Byzantine tradition.": "Sanctify є також у традиційному латинському виданні, з календарем 1962 року й поясненням латинської меси, і в східнокатолицькому виданні для візантійської традиції.",
