"Moderator": "Модератор",
"You can do everything a moderator can, and choose the moderators from a member’s page in Moderate.": "Ви можете все, що й модератор, і призначаєте модераторів на сторінці учасника в розділі «Модерація».",
"You can remove any post or reply, pin and lock threads, review reports, see every account, and mute, warn, or ban members.": "Ви можете прибирати будь-які дописи й відповіді, закріплювати й закривати теми, розглядати скарги, бачити всі облікові записи, а також глушити, попереджати й блокувати учасників.",
"Open moderation tools": "Відкрити інструменти модерації",
"Delete my account": "Видалити обліковий запис",
"This signs you out everywhere and frees up your username. Your posts and replies stay up, shown as written by a “Former member.” If you’d like any of them gone, delete them first.": "Це виведе вас з усіх сеансів і звільнить ім’я користувача. Ваші дописи й відповіді залишаться, підписані «Колишній учасник». Якщо хочете щось прибрати, видаліть це заздалегідь.",
